@spec vm_extra_cols_spec  src=tests/specs/vm_extra_cols_spec.lua  loc=207  cases=5
@exercises trackerView (h.vm), editCursor (h.ec), dataStore (h.ds), trackerManager (h.tm)
@surface   vm:setGridSize, ec:setPos, vm:hideExtraCol, ds:get, ds:assign, tm:rebuild, tm:addEvent, tm:flush
@harness   mk{seed.notes}

# Intent
  Pins hideExtraCol's contract: only the topmost empty lane drops, from
  any lane. See docs/trackerView.md § Extra columns & delay sub-column.

# Helpers
  @fn noteColsOn(h, chan)  @ 17-23

# Cases
  @case 'hideExtraCol on topmost empty note lane shrinks extraColumns'  [harness]  @ 28-61
  @case 'hideExtraCol from a lower lane drops the topmost empty lane'  [harness]  @ 65-95
  @case 'hideExtraCol with an occupied top lane is a no-op'  [harness]  @ 99-135
  @case 'hideExtraCol drops the top authored lane past a provisional one'  [harness]  @ 139-172
  @case 'hiding a provisional cc column is a no-op -- it comes straight back'  [harness]  @ 176-204

# Uses (outbound edges)
  @use call vm:setGridSize  @ 39,78,112,152,181
